// ─── File: src/test/java/com/bank/concpar/ConcurrencyVsParallelismTest.java ───
package com.bank.concpar;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class ConcurrencyVsParallelismTest {

    // ═══ IO-BOUND: concurrency — many threads, mostly waiting ═══
    @Test
    void ioBound_manyConcurrentThreads() throws InterruptedException {
        int tasks = 20;
        ExecutorService ioPool = Executors.newFixedThreadPool(20);
        CountDownLatch latch = new CountDownLatch(tasks);

        long start = System.currentTimeMillis();
        for (int i = 0; i < tasks; i++) {
            ioPool.submit(() -> {
                try { Thread.sleep(200); }  // simulate 200ms IO wait
                catch (InterruptedException e) { }
                latch.countDown();
            });
        }
        latch.await();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isLessThan(500);  // ~200ms (concurrent!), not 4000ms!
        ioPool.shutdown();
    }

    // ═══ CPU-BOUND: parallelism — cores threads ═══
    @Test
    void cpuBound_coresThreads() {
        int cores = Runtime.getRuntime().availableProcessors();
        long[] data = new long[100_000];
        Arrays.fill(data, 42L);

        // Parallel stream uses ForkJoinPool (cores threads)
        long start = System.nanoTime();
        long sum = Arrays.stream(data).parallel().map(v -> v * v).sum();  // CPU work!
        long parallelMs = (System.nanoTime() - start) / 1_000_000;

        long start2 = System.nanoTime();
        long sum2 = Arrays.stream(data).map(v -> v * v).sum();  // sequential
        long seqMs = (System.nanoTime() - start2) / 1_000_000;

        assertThat(sum).isEqualTo(sum2);
        System.out.println("Cores: " + cores + ", Parallel: " + parallelMs + "ms, Sequential: " + seqMs + "ms");
    }

    // ═══ SEPARATE POOLS: IO + CPU ═══
    @Test
    void separatePools_ioAndCpu() throws InterruptedException {
        int cores = Runtime.getRuntime().availableProcessors();
        ExecutorService ioPool = Executors.newFixedThreadPool(20);
        ExecutorService cpuPool = Executors.newFixedThreadPool(cores);
        CountDownLatch done = new CountDownLatch(2);

        // IO tasks: 20 DB queries concurrently
        ioPool.submit(() -> {
            try {
                List<Future<?>> futures = new ArrayList<>();
                for (int i = 0; i < 20; i++) {
                    futures.add(ioPool.submit(() -> {
                        try { Thread.sleep(100); } catch (InterruptedException e) { }
                    }));
                }
                for (Future<?> f : futures) f.get();
            } catch (Exception e) { }
            done.countDown();
        });

        // CPU tasks: encrypt on all cores
        cpuPool.submit(() -> {
            long sum = 0;
            for (int i = 0; i < 1_000_000; i++) sum += i * i;
            done.countDown();
        });

        done.await(10, TimeUnit.SECONDS);
        ioPool.shutdown();
        cpuPool.shutdown();
    }
}
